(() => {
 'use strict';
 const auth=window.ColorWinAuth;
 let owner='',started=Date.now(),busy=false,timer=0,active=null,queue=[],seen=new Set();
 function clear(){clearTimeout(timer);document.querySelector('#deposit-notification-banner')?.remove();active=null;queue=[];seen=new Set();}
 function show(){if(active||!queue.length)return;active=queue.shift();const banner=document.createElement('section');banner.id='deposit-notification-banner';banner.className='deposit-push';banner.setAttribute('role','status');banner.setAttribute('aria-live','polite');banner.innerHTML='<div class="deposit-push-icon" aria-hidden="true"><img src="assets/icons/deposit-money.svg?v=green-2" alt=""></div><button class="deposit-push-open" type="button"><small>COLOR WIN · DEPOSIT</small><strong></strong><span></span></button><button class="deposit-push-close" type="button" aria-label="Dismiss deposit notification">×</button>';banner.querySelector('strong').textContent=active.title;banner.querySelector('.deposit-push-open span').textContent=String(active.message||'').replace(/\s*Order\s*:.*$/is,'').trim();const close=()=>{clearTimeout(timer);banner.remove();active=null;show();};banner.querySelector('.deposit-push-close').onclick=close;banner.querySelector('.deposit-push-open').onclick=()=>{location.hash='#/account/notifications';close();};document.body.append(banner);timer=setTimeout(close,5000);window.ColorWinAccount?.refreshBalance?.().catch(()=>{});}
 async function poll(){const user=auth.session?.user?.id||'';if(user!==owner){owner=user;started=Date.now();clear();}if(!owner||owner==='preview'||busy||!auth.depositNotices)return;const expected=owner;busy=true;try{const notices=await auth.depositNotices();if(auth.session?.user?.id!==expected)return;for(const n of [...notices].reverse()){if(seen.has(n.id))continue;seen.add(n.id);if(new Date(n.created_at).getTime()<started)continue;queue.push(n);}show();}catch{/* Saved notifications remain available; retry on the next poll. */}finally{busy=false;}}
 auth.init(()=>{if(auth.ready)poll();});setInterval(poll,3000);window.addEventListener('focus',poll);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
